#include <vector>
#include <iostream>

int main() {
    std::vector<int> v = {1, 5, 2, 5, 3, 5};

    // Safe deletion loop using the return value of erase
    for (auto it = v.begin(); it != v.end(); /* increment inside */) {
        if (*it == 5) {
            // 'it' is invalidated. Capture the new iterator.
            it = v.erase(it); 
        } else {
            ++it; // Only increment if no deletion occurred
        }
    }

    // v is now {1, 2, 3}
    // auto danger_it = v.begin();
    // v.erase(v.begin());
    // *danger_it; // DANGER: UB if not handled
}
